      "assessment": {
        "nobel_worthiness": "Optical-lattice simulators made strongly correlated quantum matter controllable and observable with a degree of microscopic control unavailable in conventional materials.",
        "attribution": "Bloch and Greiner supplied defining experimental demonstrations; Zoller's theoretical work helped establish the simulator framework and its targets.",
        "maturity": "The approach is experimentally mature, widely replicated, and has generated a sustained body of quantitative many-body results.",
        "uncertainties": [
          "Credit boundaries with broader cold-atom and quantum-simulation foundations need scrutiny."
        ]
      }
    },
